const definitions={grammar:{title:'Gramática',intro:'Treine relações e estruturas. Não uma apostila.',normal:'Estruturas',normalCopy:'Partículas, negação, passado e formas em contexto.',end:'FRACTURE',endCopy:'Reconstrua frases quebradas sem fingir que japonês tem uma única ordem.'},listening:{title:'Escuta',intro:'Som primeiro. O texto não vai salvar você.',normal:'Escuta guiada',normalCopy:'Ouça palavras e frases naturais com repetição livre.',end:'VOID',endCopy:'Sem transcrição. Um áudio. Uma chance.'},reading:{title:'Leitura',intro:'Leia para compreender o que aconteceu, não para traduzir linha por linha.',normal:'Compreensão',normalCopy:'Textos curtos e perguntas sobre o conteúdo.',end:'LABYRINTH',endCopy:'O português desaparece enquanto você avança.'}};
