function statFor(name){return stats[name]||{hits:0,errors:0,sessions:0,best:0};}
function openMode(name){mode=name;hideBase();play.hidden=false;$('p3Intro').hidden=false;$('p3Game').hidden=true;$('p3Result').hidden=true;const end=['fracture','void','labyrinth'].includes(name),titles={grammar:'ESTRUTURAS',fracture:'FRACTURE',listening:'ESCUTA',void:'VOID',reading:'COMPREENSÃO',labyrinth:'LABYRINTH'},copies={grammar:'Escolha a estrutura que completa ou explica a frase.',fracture:'Toque nos blocos para reconstruir a frase. Ordens alternativas válidas são aceitas.',listening:'Ouça quantas vezes precisar e reconheça o conceito.',void:'Nenhuma transcrição. O áudio toca uma vez.',reading:'Leia e responda sobre o que aconteceu.',labyrinth:'As perguntas e respostas abandonam o português progressivamente.'};$('p3Eyebrow').textContent=`${territory} · ${end?'endgame':'treino'}`;$('p3Title').textContent=titles[name];$('p3IntroCopy').textContent=copies[name];const s=statFor(name),total=s.hits+s.errors;$('p3Record').textContent=`${total?Math.round(s.hits/total*100):0}% geral${end?` · recorde ${s.best||0}`:''}`;$('p3Start').onclick=startRun;}
function startRun(){turn=0;cycleIndex=0;hits=0;errors=0;streak=0;selected=[];buildCycle();session={id:root.KANA_PERSISTENCE.uuid(),mode,territory,startedAt:Date.now()};$('p3Intro').hidden=true;$('p3Result').hidden=true;$('p3Game').hidden=false;next();saveSession();}
